// Attach the FMP array (or error) to its watchlist row, pairing by item index.
const rows = $('Lane by Venue').all(0).map(i => i.json);
return $input.all().map((it, idx) => {
  const j = it.json;
  const history = Array.isArray(j) ? j : (Array.isArray(j.data) ? j.data : null);
  return { json: { ...rows[idx], history, error: j.error || (history ? undefined : 'unexpected FMP shape') } };
});

// Normalize FMP — turn one symbol's EOD-light history (newest first) into the fields the evaluator needs.
// Input item: { symbol, venue, alert_type, threshold, note, cooldown_h, last_alert_at, history: [{date, price, volume}] }
// (the HTTP node's array is attached as `history` by the preceding Merge/Set; a failed fetch has `error`).
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.error || !Array.isArray(j.history) || j.history.length < 2) {
    out.push({ json: { ...j, price: null, prev_close: null, change_pct: null, high52: null, low52: null, asof: null, fetch_error: j.error ? String(j.error.message || j.error) : 'no history' } });
    continue;
  }
  const h = [...j.history].sort((a, b) => (a.date < b.date ? 1 : -1)); // newest first
  const price = Number(h[0].price), prev = Number(h[1].price);
  const year = h.slice(0, 252).map((r) => Number(r.price)).filter((n) => Number.isFinite(n));
  out.push({ json: {
    ...j, history: undefined,
    price, prev_close: prev,
    change_pct: prev ? ((price - prev) / prev) * 100 : null,
    high52: Math.max(...year), low52: Math.min(...year),
    asof: h[0].date
  } });
}
return out;

// Evaluate Alerts — one item per watchlist row with price fields already attached
// (FMP branch via Normalize FMP, PSE branch straight from the sheet's GOOGLEFINANCE columns).
// Emits ONE Telegram message item plus one `updates` array for the sheet write-back.
const TZ = 'Asia/Manila';
const now = DateTime.now().setZone(TZ);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = (v) => {
  if (v == null || v === '') return null;
  const n = Number(String(v).replace(/[,%$₱\s]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const money = (v, venue) => (v == null ? '—' : (venue === 'PSE' ? '₱' : '$') + Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 }));
const pct = (v) => (v == null ? '' : `${v >= 0 ? '+' : ''}${v.toFixed(1)}%`);

const fired = [], errors = [], updates = [];
for (const { json: r } of $input.all()) {
  if (String(r.active).toUpperCase() === 'FALSE' || r.active === false || !r.symbol) continue;
  const venue = String(r.venue || 'US').toUpperCase();
  const price = num(r.price), prev = num(r.prev_close), high52 = num(r.high52), low52 = num(r.low52);
  const changePct = r.change_pct != null ? num(r.change_pct) : (price && prev ? ((price - prev) / prev) * 100 : null);
  if (price == null) { errors.push(`${r.symbol}: ${esc(r.fetch_error || 'no price')}`); continue; }
  const threshold = num(r.threshold);
  const type = String(r.alert_type || '').toLowerCase();
  let hit = false, why = '';
  if (type === 'above' && threshold != null && price >= threshold) { hit = true; why = `above ${money(threshold, venue)}`; }
  else if (type === 'below' && threshold != null && price <= threshold) { hit = true; why = `below ${money(threshold, venue)}`; }
  else if (type === 'pct_day' && threshold != null && changePct != null && Math.abs(changePct) >= threshold) { hit = true; why = `moved ${pct(changePct)} (≥${threshold}%)`; }
  else if (type === 'breakout_52w' && high52 != null && price >= high52 * 0.995) { hit = true; why = `at 52-week high ${money(high52, venue)}`; }
  else if (type === 'drawdown_from_high' && threshold != null && high52) {
    const dd = ((high52 - price) / high52) * 100;
    if (dd >= threshold) { hit = true; why = `${dd.toFixed(0)}% below its 52-week high ${money(high52, venue)}`; }
  }
  const cooldownH = num(r.cooldown_h) ?? 24;
  const last = r.last_alert_at ? DateTime.fromISO(String(r.last_alert_at), { zone: TZ }) : null;
  const cooled = !last || !last.isValid || now.diff(last, 'hours').hours >= cooldownH;
  updates.push({ symbol: r.symbol, last_price: price, last_checked_at: now.toISO(), ...(hit && cooled ? { last_alert_at: now.toISO() } : {}) });
  if (hit && cooled) {
    const icon = type === 'below' || type === 'drawdown_from_high' || (changePct != null && changePct < 0) ? '📉' : '📈';
    fired.push(`${icon} <b>${esc(r.symbol)}</b> ${money(price, venue)} ${pct(changePct)} — ${why}${r.note ? ` <i>(${esc(r.note)})</i>` : ''}`);
  }
}

if (!fired.length && !errors.length) return [{ json: { send: false, updates } }];
const head = `<b>📊 Price alerts</b> · ${now.toFormat('ccc d LLL')}`;
const body = fired.length ? fired.join('\n') : '<i>no thresholds crossed</i>';
const foot = errors.length ? `\n<i>unavailable: ${errors.join(' · ')}</i>` : '';
return [{ json: { send: fired.length > 0, text: `${head}\n${body}${foot}`, fired: fired.length, updates } }];
